                  const normalizeCountryName = (raw) => {
                    if (!raw) return 'Unknown Geography';
                    const str = String(raw).trim();
                    const lower = str.toLowerCase();
                    if (COUNTRY_NORM_MAP[lower]) return COUNTRY_NORM_MAP[lower];

                    if (/ee.?s*uu.?|estadoss+unidos|usa|u.s.a/i.test(str)) return 'United States';
                    if (/puertos+rico/i.test(str)) return 'Puerto Rico';
                    if (/reinos+unido|grans+breta[ñn]a|uniteds+kingdom/i.test(str)) return 'United Kingdom';
                    if (/francia/i.test(str)) return 'France';
                    if (/alemania|deutschland/i.test(str)) return 'Germany';
                    if (/espa[ñn]a/i.test(str)) return 'Spain';
                    if (/italia/i.test(str)) return 'Italy';

                    return str.charAt(0).toUpperCase() + str.slice(1);
                  };

