                  const findCountryFeature = (countryName) => {
                    const normName = normalizeCountryName(countryName);
                    const lower = normName.toLowerCase();

                    // 1. Direct match in WORLD_MAP_FEATURES
                    const feat = WORLD_MAP_FEATURES.find(f => f.name.toLowerCase() === lower || (f.aliases && f.aliases.includes(lower)));
                    if (feat) return feat;

                    // 2. Lookup in ALL_COUNTRY_CENTROIDS
                    const fallback = ALL_COUNTRY_CENTROIDS[lower];
                    if (fallback) {
                      const cx = ((fallback.lng + 180) / 360) * 1000;
                      const cy = ((90 - fallback.lat) / 180) * 500;
                      const r = 9;
                      return {
                        id: lower.slice(0, 3).toUpperCase(),
                        name: normName,
                        geoCoords: fallback,
                        centroid: { x: cx, y: cy },
                        path: `M ${cx - r},${cy} L ${cx},${cy - r} L ${cx + r},${cy} L ${cx},${cy + r} Z`
                      };
                    }

                    return null;
                  };

