    const normalizeRoute = (rawRoute) => {
      if (!rawRoute) return 'overview';
      const clean = String(rawRoute).replace(/^#[\/]?/, '').trim();
      const firstSegment = clean.split('/')[0].split('?')[0].toLowerCase();
      return ROUTE_ALIASES[firstSegment] || null;
    };

    /* Dashboard Navigation State (URL Synchronized with Invariant Guarantees) */
    const getNavFromLocation = () => {
      const hash = (window.location.hash || '').replace(/^#[\/]?/, '').trim();
      const path = (window.location.pathname || '').replace(/^\//, '').trim();
      const rawRoute = hash || path;
      const normalized = normalizeRoute(rawRoute);

      if (!normalized) {
        // Invariant E: Invalid destinations recover safely to 'overview'
        // Invariant H: Synchronize URL and React state via replaceState without polluting history
        if (window.location.hash && window.location.hash !== '#/' && window.location.hash !== '#/overview') {
          try {
            history.replaceState(null, '', '#/overview');
          } catch (e) {
            window.location.hash = '#/overview';
          }
        }
        return 'overview';
      }

      // Canonicalize root hash '#', '#/' or empty to preferred landing or '#/overview'
      if (!hash || hash === '/' || hash === '') {
        const preferred = localStorage.getItem('insightiq_settings_landing_page');
        const target = (preferred && ROUTE_ALIASES[preferred]) ? ROUTE_ALIASES[preferred] : 'overview';
        try {
          history.replaceState(null, '', `#/${target}`);
        } catch (e) {}
        return target;
      }

      return normalized;
    };

