    if (!window._datasetPreprocessedCache) window._datasetPreprocessedCache = {};

    /* High-Performance One-Time Dataset Preprocessing & Filter Options Cache */
    const preprocessDatasetRowsAndOptions = (datasetId, columns = [], rows = []) => {
      if (!datasetId || !rows || rows.length === 0) {
        return {
          rows: [],
          filterOptions: { regions: [], countries: [], categories: [], products: [], segments: [] },
          maxDatasetDate: new Date(),
          candidateCols: {}
        };
      }

      if (window._datasetPreprocessedCache && window._datasetPreprocessedCache[datasetId]) {
        return window._datasetPreprocessedCache[datasetId];
      }

      const normKey = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
      const dateCol = columns.find(c => c.is_temporal || ['date', 'timestamp', 'createdat', 'recorddate', 'time', 'dateorders'].some(k => normKey(c.column_name).includes(k)))?.column_name;
      const revCol = columns.find(c => ['revenue', 'sales', 'salesamount', 'totalsales', 'amount', 'grosssales', 'income', 'spend', 'quarterlyrevenue', 'monthlyspend', 'dailyrevenue'].some(k => normKey(c.column_name).includes(k)))?.column_name;
      const profitCol = columns.find(c => ['profit', 'netprofit', 'profitamount', 'netincome', 'margin', 'operatingexpense', 'orderprofitperorder'].some(k => normKey(c.column_name).includes(k)))?.column_name;
      const orderCol = (columns.find(c => normKey(c.column_name) === 'orderid') ||
                        columns.find(c => c.is_identifier && normKey(c.column_name).includes('order') && !normKey(c.column_name).includes('customer')) ||
                        columns.find(c => ['orderid', 'ordernumber', 'transactionid', 'invoiceid'].some(k => normKey(c.column_name).includes(k))))?.column_name;
      const custCol = (columns.find(c => normKey(c.column_name) === 'ordercustomerid' || normKey(c.column_name) === 'customerid') ||
                       columns.find(c => c.is_identifier && (normKey(c.column_name).includes('customer') || normKey(c.column_name).includes('cust'))))?.column_name;
      const regionCol = columns.find(c => ['region', 'orderregion', 'location', 'state', 'province', 'market', 'territory'].some(k => normKey(c.column_name).includes(k)))?.column_name;
      const countryCol = columns.find(c => ['country', 'ordercountry', 'nation', 'countryname'].some(k => normKey(c.column_name).includes(k)))?.column_name;
      const categoryCol = columns.find(c => ['category', 'categoryname', 'subscriptiontier', 'type', 'tier', 'group'].some(k => normKey(c.column_name).includes(k)))?.column_name;
      const productCol = columns.find(c => ['product', 'productname', 'item'].some(k => normKey(c.column_name).includes(k)))?.column_name;
      const segmentCol = columns.find(c => ['segment', 'customersegment', 'tier', 'group'].some(k => normKey(c.column_name).includes(k)))?.column_name;
      const statusCol = columns.find(c => ['status', 'state', 'orderstatus'].some(k => normKey(c.column_name).includes(k)))?.column_name;

      const regSet = new Set();
      const countrySet = new Set();
      const catSet = new Set();
      const prodSet = new Set();
      const segSet = new Set();

      let maxDsMs = 0;

      for (let i = 0; i < rows.length; i++) {
        const r = rows[i];
        
        // Fast numeric normalization
        if (r._rev === undefined) {
          const revVal = revCol ? r[revCol] : undefined;
          r._rev = typeof revVal === 'number' ? revVal : parseFloat(String(revVal || 0).replace(/[$€£¥,]/g, '')) || 0;
        }

        if (r._profit === undefined) {
          const profitVal = profitCol ? r[profitCol] : undefined;
          r._profit = typeof profitVal === 'number' ? profitVal : parseFloat(String(profitVal || 0).replace(/[$€£¥,]/g, '')) || 0;
        }

        // Fast timestamp normalization
        if (r._ts === undefined) {
          if (dateCol && r[dateCol]) {
            const ms = Date.parse(r[dateCol]);
            r._ts = !isNaN(ms) ? ms : 0;
          } else {
            r._ts = 0;
          }
        }

        if (r._ts > maxDsMs) maxDsMs = r._ts;

        // Fast string normalization
        if (r._reg === undefined) r._reg = regionCol && r[regionCol] ? String(r[regionCol]).trim() : '';
        if (r._country === undefined) r._country = countryCol && r[countryCol] ? String(r[countryCol]).trim() : '';
        if (r._cat === undefined) r._cat = categoryCol && r[categoryCol] ? String(r[categoryCol]).trim() : '';
        if (r._prod === undefined) r._prod = productCol && r[productCol] ? String(r[productCol]).trim() : '';
        if (r._seg === undefined) r._seg = segmentCol && r[segmentCol] ? String(r[segmentCol]).trim() : '';

        // Collect unique filter options from active dataset
        if (r._reg) regSet.add(r._reg);
        if (r._country) countrySet.add(r._country);
        if (r._cat) catSet.add(r._cat);
        if (r._prod) prodSet.add(r._prod);
        if (r._seg) segSet.add(r._seg);
      }

      const maxDatasetDate = maxDsMs > 0 ? new Date(maxDsMs) : new Date();

      const filterOptions = {
        regions: Array.from(regSet).filter(Boolean).sort(),
        countries: Array.from(countrySet).filter(Boolean).sort(),
        categories: Array.from(catSet).filter(Boolean).sort(),
        products: Array.from(prodSet).filter(Boolean).sort(),
        segments: Array.from(segSet).filter(Boolean).sort()
      };

      const candidateCols = {
        dateCol, revCol, profitCol, orderCol, custCol, regionCol, countryCol, categoryCol, productCol, segmentCol, statusCol
      };

      const result = { rows, filterOptions, maxDatasetDate, candidateCols };

      window._datasetPreprocessedCache[datasetId] = result;
      return result;
    };

    /* Data Catalog Interactive UX State & URL Query Sync */
    const parseUrlFilters = () => {
      try {
        const params = new URLSearchParams(window.location.search);
        const parseArray = (key) => {
          const val = params.get(key);
          if (!val) return [];
          return val.split(',').map(s => s.trim()).filter(Boolean);
        };

        const saved = localStorage.getItem('insightiq_global_filters');
        let savedObj = {};
        if (saved) {
          try { savedObj = JSON.parse(saved); } catch (e) {}
        }

        return {
          dateRange: params.get('dateRange') || savedObj.dateRange || 'All Time',
          startDate: params.get('startDate') || savedObj.startDate || '',
          endDate: params.get('endDate') || savedObj.endDate || '',
          region: parseArray('region').length > 0 ? parseArray('region') : (Array.isArray(savedObj.region) ? savedObj.region : (savedObj.region ? [savedObj.region] : [])),
          country: parseArray('country').length > 0 ? parseArray('country') : (Array.isArray(savedObj.country) ? savedObj.country : (savedObj.country ? [savedObj.country] : [])),
          category: parseArray('category').length > 0 ? parseArray('category') : (Array.isArray(savedObj.category) ? savedObj.category : (savedObj.category ? [savedObj.category] : [])),
          product: parseArray('product').length > 0 ? parseArray('product') : (Array.isArray(savedObj.product) ? savedObj.product : (savedObj.product ? [savedObj.product] : [])),
          segment: parseArray('segment').length > 0 ? parseArray('segment') : (Array.isArray(savedObj.segment) ? savedObj.segment : (savedObj.segment ? [savedObj.segment] : []))
        };
      } catch (e) {
        return { dateRange: 'All Time', startDate: '', endDate: '', region: [], country: [], category: [], product: [], segment: [] };
      }
    };

    const [catalogSearchQuery, setCatalogSearchQuery] = React.useState('');
    const [globalFilters, setGlobalFilters] = React.useState(parseUrlFilters);
    const [openFilterDropdown, setOpenFilterDropdown] = React.useState(null);

    React.useEffect(() => {
      try {
        const params = new URLSearchParams();
        if (globalFilters.dateRange && globalFilters.dateRange !== 'All Time') params.set('dateRange', globalFilters.dateRange);
        if (globalFilters.startDate) params.set('startDate', globalFilters.startDate);
        if (globalFilters.endDate) params.set('endDate', globalFilters.endDate);

        if (Array.isArray(globalFilters.region) && globalFilters.region.length > 0) params.set('region', globalFilters.region.join(','));
        if (Array.isArray(globalFilters.country) && globalFilters.country.length > 0) params.set('country', globalFilters.country.join(','));
        if (Array.isArray(globalFilters.category) && globalFilters.category.length > 0) params.set('category', globalFilters.category.join(','));
        if (Array.isArray(globalFilters.product) && globalFilters.product.length > 0) params.set('product', globalFilters.product.join(','));
        if (Array.isArray(globalFilters.segment) && globalFilters.segment.length > 0) params.set('segment', globalFilters.segment.join(','));

        const queryString = params.toString();
        const newUrl = window.location.pathname + (queryString ? `?${queryString}` : '');
        if (window.location.search !== (queryString ? `?${queryString}` : '')) {
          window.history.replaceState(null, '', newUrl);
        }
        localStorage.setItem('insightiq_global_filters', JSON.stringify(globalFilters));
      } catch (e) {}
    }, [globalFilters]);
    const [catalogStatusFilter, setCatalogStatusFilter] = React.useState('all');
    const [columnSearchQuery, setColumnSearchQuery] = React.useState(''); // 'all' | 'active' | 'processing' | 'failed'
