                  const selectedDs = userDatasets.find(d => d.id === activeDsId) || (activeDatasetDetails?.dataset) || userDatasets[0];
                  const rawRows = window._datasetRowsStore ? (window._datasetRowsStore[selectedDs?.id] || (activeDatasetDetails?.rawRows || [])) : (activeDatasetDetails?.rawRows || []);
                  const cols = (activeDatasetDetails && activeDatasetDetails.dataset?.id === selectedDs?.id && activeDatasetDetails.columns && activeDatasetDetails.columns.length > 0)
